        style = style.copy(paddingRight = 26.dp)
        style = style.copy(iconRight = 8.dp)
        style = style.copy(fontSize = 12.dp)
        style = style.copy(borderRadius = CocsoTokens.Radius.r3)
    }
    if (size == CCSelectSize.small) {
        style = style.copy(minWidth = 32.dp)
        style = style.copy(height = 32.dp)
        style = style.copy(paddingLeft = 10.dp)
        style = style.copy(paddingRight = 32.dp)
        style = style.copy(iconRight = 10.dp)
        style = style.copy(fontSize = 12.dp)
        style = style.copy(borderRadius = CocsoTokens.Radius.r3)
    }
    if (size == CCSelectSize.medium) {
        style = style.copy(minWidth = 36.dp)
        style = style.copy(height = 36.dp)
        style = style.copy(paddingLeft = 12.dp)
