enum class CCSkeletonVariant {
    text,
    circular,
    rectangular,
}

enum class CCSkeletonAnimation {
    pulse,
    wave,
    none,
}

data class CCSkeletonStyle(
    val bgColor: ComposeColor? = null,
    val height: Dp? = null,
    val borderRadius: Dp? = null,
    val width: Dp? = null,
)

@Composable
@ReadOnlyComposable
fun cCSkeletonStyle(
    variant: CCSkeletonVariant,
    animation: CCSkeletonAnimation,
): CCSkeletonStyle {
    var style = CCSkeletonStyle()
    style = style.copy(bgColor = CocsoTokens.Color.surfaceNeutral())
    if (variant == CCSkeletonVariant.text) {
        style = style.copy(height = 16.dp)
        style = style.copy(borderRadius = CocsoTokens.Radius.r2)
    }
    if (variant == CCSkeletonVariant.circular) {
        style = style.copy(height = 40.dp)
        style = style.copy(width = 40.dp)
    }
    if (variant == CCSkeletonVariant.rectangular) {
        style = style.copy(height = 120.dp)
        style = style.copy(borderRadius = CocsoTokens.Radius.r4)
    }
    return style
}

enum class CCSpinnerVariant {
    primary,
    secondary,
    success,
    error,
    warning,
    info,
    white,
}

enum class CCSpinnerSize {
    large,
    medium,
    small,
}

data class CCSpinnerStyle(
    val bladeColor: ComposeColor? = null,
    val blades: Dp? = null,
    val bladeWidth: Dp? = null,
    val bladeHeight: Dp? = null,
    val output: Dp? = null,
)

@Composable
@ReadOnlyComposable
fun cCSpinnerStyle(
    variant: CCSpinnerVariant,
    size: CCSpinnerSize,
): CCSpinnerStyle {
    var style = CCSpinnerStyle()
    if (variant == CCSpinnerVariant.primary) {
        style = style.copy(bladeColor = CocsoTokens.Color.interactivePrimary())
    }
    if (variant == CCSpinnerVariant.secondary) {
        style = style.copy(bladeColor = CocsoTokens.Color.textMuted())
    }
    if (variant == CCSpinnerVariant.success) {
        style = style.copy(bladeColor = CocsoTokens.Color.feedbackSuccess())
    }
    if (variant == CCSpinnerVariant.error) {
        style = style.copy(bladeColor = CocsoTokens.Color.feedbackDanger())
    }
    if (variant == CCSpinnerVariant.warning) {
        style = style.copy(bladeColor = CocsoTokens.Color.feedbackWarning())
    }
    if (variant == CCSpinnerVariant.info) {
        style = style.copy(bladeColor = CocsoTokens.Color.feedbackInfo())
    }
    if (variant == CCSpinnerVariant.white) {
        style = style.copy(bladeColor = CocsoTokens.Color.surfacePrimary())
    }
    if (size == CCSpinnerSize.large) {
        style = style.copy(blades = 10.dp)
        style = style.copy(bladeWidth = 2.dp)
        style = style.copy(bladeHeight = 6.dp)
        style = style.copy(output = 20.dp)
    }
    if (size == CCSpinnerSize.medium) {
        style = style.copy(blades = 8.dp)
        style = style.copy(bladeWidth = 2.dp)
        style = style.copy(bladeHeight = 5.dp)
        style = style.copy(output = 16.dp)
    }
    if (size == CCSpinnerSize.small) {
        style = style.copy(blades = 6.dp)
        style = style.copy(bladeWidth = 1.5.dp)
        style = style.copy(bladeHeight = 4.dp)
        style = style.copy(output = 12.dp)
    }
    return style
}

