enum class CCSwitchVariant {
    primary,
    success,
    error,
    warning,
    info,
}

enum class CCSwitchSize {
    large,
    medium,
    small,
}

enum class CCSwitchChecked {
    `true`,
    `false`,
}

data class CCSwitchStyle(
    val switchBgColor: ComposeColor? = null,
    val checkedBgColor: ComposeColor? = null,
    val width: Dp? = null,
    val height: Dp? = null,
    val thumbSize: Dp? = null,
    val thumbOffset: Dp? = null,
)

@Composable
@ReadOnlyComposable
fun cCSwitchStyle(
    variant: CCSwitchVariant,
    size: CCSwitchSize,
    checked: CCSwitchChecked,
): CCSwitchStyle {
    var style = CCSwitchStyle()
    style = style.copy(switchBgColor = CocsoTokens.Color.surfaceNeutral())
    if (variant == CCSwitchVariant.primary) {
        style = style.copy(checkedBgColor = CocsoTokens.Color.interactivePrimary())
    }
    if (variant == CCSwitchVariant.success) {
        style = style.copy(checkedBgColor = CocsoTokens.Color.interactiveSuccess())
    }
    if (variant == CCSwitchVariant.error) {
        style = style.copy(checkedBgColor = CocsoTokens.Color.interactiveDanger())
    }
    if (variant == CCSwitchVariant.warning) {
        style = style.copy(checkedBgColor = CocsoTokens.Color.interactiveWarningActive())
    }
    if (variant == CCSwitchVariant.info) {
        style = style.copy(checkedBgColor = CocsoTokens.Color.interactiveInfo())
    }
    if (size == CCSwitchSize.large) {
        style = style.copy(width = 40.dp)
        style = style.copy(height = 22.dp)
        style = style.copy(thumbSize = 18.dp)
        style = style.copy(thumbOffset = 2.dp)
    }
    if (size == CCSwitchSize.medium) {
        style = style.copy(width = 36.dp)
        style = style.copy(height = 20.dp)
        style = style.copy(thumbSize = 16.dp)
        style = style.copy(thumbOffset = 2.dp)
    }
    if (size == CCSwitchSize.small) {
        style = style.copy(width = 32.dp)
        style = style.copy(height = 18.dp)
        style = style.copy(thumbSize = 14.dp)
        style = style.copy(thumbOffset = 2.dp)
    }
    if (variant == CCSwitchVariant.primary && checked == CCSwitchChecked.`true`) {
        style = style.copy(switchBgColor = CocsoTokens.Color.interactivePrimary())
    }
    if (variant == CCSwitchVariant.success && checked == CCSwitchChecked.`true`) {
        style = style.copy(switchBgColor = CocsoTokens.Color.interactiveSuccess())
    }
    if (variant == CCSwitchVariant.error && checked == CCSwitchChecked.`true`) {
        style = style.copy(switchBgColor = CocsoTokens.Color.interactiveDanger())
    }
    if (variant == CCSwitchVariant.warning && checked == CCSwitchChecked.`true`) {
        style = style.copy(switchBgColor = CocsoTokens.Color.interactiveWarningActive())
    }
    if (variant == CCSwitchVariant.info && checked == CCSwitchChecked.`true`) {
        style = style.copy(switchBgColor = CocsoTokens.Color.interactiveInfo())
    }
    return style
}

enum class CCTypographyType {
    body,
    heading,
}

enum class CCTypographySize {
    xLarge,
    large,
    medium,
    small,
    xSmall,
}

data class CCTypographyStyle(
    val fontWeight: FontWeight? = null,
    val fontSize: Dp? = null,
)

@Composable
@ReadOnlyComposable
fun cCTypographyStyle(
    type: CCTypographyType,
    size: CCTypographySize,
): CCTypographyStyle {
    var style = CCTypographyStyle()
    if (type == CCTypographyType.heading) {
        style = style.copy(fontWeight = FontWeight.Bold)
    }
    if (size == CCTypographySize.xLarge) {
        style = style.copy(fontSize = 28.dp)
    }
    if (size == CCTypographySize.large) {
        style = style.copy(fontSize = 24.dp)
    }
    if (size == CCTypographySize.medium) {
        style = style.copy(fontSize = 20.dp)
    }
    if (size == CCTypographySize.small) {
        style = style.copy(fontSize = 16.dp)
    }
    if (size == CCTypographySize.xSmall) {
        style = style.copy(fontSize = 14.dp)
    }
    if (type == CCTypographyType.body && size == CCTypographySize.xLarge) {
        style = style.copy(fontSize = 18.dp)
    }
    if (type == CCTypographyType.body && size == CCTypographySize.large) {
        style = style.copy(fontSize = 18.dp)
    }
    if (type == CCTypographyType.body && size == CCTypographySize.medium) {
        style = style.copy(fontSize = 16.dp)
    }
    if (type == CCTypographyType.body && size == CCTypographySize.small) {
        style = style.copy(fontSize = 14.dp)
    }
    if (type == CCTypographyType.body && size == CCTypographySize.xSmall) {
        style = style.copy(fontSize = 12.dp)
    }
    return style
}
